  val BY_ID: Map<String, Entry> = ALL.associateBy { it.id }

  fun currentActiveEntry(context: Context): Entry {
    val pm = context.packageManager
    val pkg = context.packageName
    for (entry in ALL) {
      val state = pm.getComponentEnabledSetting(ComponentName(pkg, entry.aliasClass))
      if (state == PackageManager.COMPONENT_ENABLED_STATE_ENABLED) return entry
      if (state == PackageManager.COMPONENT_ENABLED_STATE_DEFAULT && entry.id == DEFAULT_ID) return entry
    }
    return BY_ID.getValue(DEFAULT_ID)
  }

  /** Sync Android Recents (Overview) title + icon with the active launcher alias so disguised
   *  icons never leak "RipleyOS" in the app switcher. */
  @Suppress("DEPRECATION")
  fun applyTaskDescription(activity: Activity, entry: Entry = currentActiveEntry(activity)) {
    activity.runOnUiThread {
      try {
        val td = if (Build.VERSION.SDK_INT >= 33) {
          ActivityManager.TaskDescription.Builder()
            .setLabel(entry.label)
            .setIcon(entry.iconRes)
            .build()
        } else if (Build.VERSION.SDK_INT >= 28) {
          ActivityManager.TaskDescription(entry.label, entry.iconRes)
        } else {
          ActivityManager.TaskDescription(entry.label)
        }
        activity.setTaskDescription(td)
      } catch (_: Exception) { }
    }
  }
